// Fabric Studio: declarative catalog of local, non-operational visual tools.
export const VISUAL_TOOLS = Object.freeze([
  { id: "text", category: "Elementos básicos", label: "Texto", help: "Agrega un título o una explicación.", icon: "text" },
  { id: "button", category: "Elementos básicos", label: "Botón", help: "Agrega un botón que una persona puede presionar.", icon: "button" },
  { id: "input", category: "Capturar información", label: "Escribir", help: "Permite escribir una respuesta corta.", icon: "input" },
  { id: "textarea", category: "Capturar información", label: "Texto largo", help: "Permite escribir una explicación más larga.", icon: "textarea" },
  { id: "checkbox", category: "Capturar información", label: "Marcar", help: "Permite elegir si una opción está marcada.", icon: "checkbox" },
  { id: "card", category: "Organizar pantallas", label: "Tarjeta", help: "Agrupa información relacionada en un recuadro.", icon: "card" },
].map(tool => Object.freeze(tool)));

function normalize(value) {
  return String(value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase("es").trim();
}

export function searchVisualTools(query = "") {
  const terms = normalize(query).split(/\s+/).filter(Boolean);
  return VISUAL_TOOLS.filter(tool => {
    const searchable = normalize([tool.label, tool.help, tool.category].join(" "));
    return terms.every(term => searchable.includes(term));
  });
}

import React, { useId, useMemo, useState } from "react";
import { Type, Square, TextCursorInput, AlignLeft, CheckSquare, LayoutGrid, Search } from "lucide-react";
import { Button } from "../ui/button.jsx";
import { Input } from "../ui/input.jsx";
import { Textarea } from "../ui/textarea.jsx";
import { Checkbox } from "../ui/checkbox.jsx";
import { Card, CardContent } from "../ui/card.jsx";
import { VISUAL_TOOLS, searchVisualTools } from "./toolCatalog.js";

const ICONS = { text: Type, button: Square, input: TextCursorInput, textarea: AlignLeft, checkbox: CheckSquare, card: LayoutGrid };

function ToolPreview({ tool }) {
  const fieldId = useId();
  const [pressed, setPressed] = useState(false);
  const [checked, setChecked] = useState(false);
  switch (tool.id) {
    case "text":
      return <p className="text-lg font-medium">Aquí puedes escribir un título.</p>;
    case "button":
      return <div className="space-y-2">
        <Button type="button" onClick={() => setPressed(value => !value)}>Probar botón</Button>
        <p role="status">{pressed ? "¡Presionaste el botón!" : "Presiona para probarlo."}</p>
      </div>;
    case "input":
      return <div className="space-y-2">
        <label htmlFor={fieldId}>Tu respuesta de ejemplo</label>
        <Input id={fieldId} placeholder="Escribe aquí" autoComplete="off" />
      </div>;
    case "textarea":
      return <div className="space-y-2">
        <label htmlFor={fieldId}>Tu explicación de ejemplo</label>
        <Textarea id={fieldId} placeholder="Escribe aquí" />
      </div>;
    case "checkbox":
      return <div className="flex items-center gap-2">
        <Checkbox id={fieldId} checked={checked} onCheckedChange={value => setChecked(value === true)} />
        <label htmlFor={fieldId}>Marcar esta opción de ejemplo</label>
      </div>;
    case "card":
      return <Card><CardContent className="p-4 space-y-1">
        <p className="font-medium">Mi tarjeta</p><p>Aquí va información relacionada.</p>
      </CardContent></Card>;
    default:
      return <p>Esta herramienta no tiene vista previa.</p>;
  }
}

export function VisualToolLibrary() {
  const searchId = useId();
  const headingId = useId();
  const previewId = useId();
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState(null);
  const results = useMemo(() => searchVisualTools(query), [query]);
  const categories = [...new Set(results.map(tool => tool.category))];
  const selected = VISUAL_TOOLS.find(tool => tool.id === selectedId);
  return <section aria-labelledby={headingId} className="space-y-4">
    <header>
      <h2 id={headingId} className="text-xl font-semibold">Mi caja de herramientas</h2>
      <p className="text-sm text-muted-foreground">Elige una herramienta para ver cómo funciona.</p>
    </header>
    <div className="space-y-2">
      <label htmlFor={searchId} className="font-medium">Buscar herramientas</label>
      <div className="flex items-center gap-2">
        <Search aria-hidden="true" className="h-5 w-5 shrink-0" />
        <Input id={searchId} type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Por ejemplo, botón" />
        {query && <Button type="button" variant="outline" onClick={() => setQuery("")}>Limpiar</Button>}
      </div>
      <p role="status" className="text-sm text-muted-foreground">
        {results.length === 1 ? "1 herramienta encontrada" : results.length + " herramientas encontradas"}
      </p>
    </div>
    <div className="grid gap-4 md:grid-cols-2">
      <div className="min-w-0 space-y-4">
        {results.length === 0 && <p>No encontramos herramientas. Prueba con otra palabra.</p>}
        {categories.map(category => <section key={category} className="space-y-2">
          <h3 className="font-medium">{category}</h3>
          <div className="grid gap-2 sm:grid-cols-2">
            {results.filter(tool => tool.category === category).map(tool => {
              const Icon = ICONS[tool.icon];
              return <Button key={tool.id} type="button" variant={selectedId === tool.id ? "default" : "outline"}
                aria-pressed={selectedId === tool.id} aria-controls={previewId}
                onClick={() => setSelectedId(tool.id)}
                className="h-auto min-h-12 justify-start whitespace-normal text-left gap-2 p-3">
                <Icon aria-hidden="true" className="h-5 w-5 shrink-0" />
                <span className="min-w-0">{tool.label}<span className="block text-xs font-normal">{tool.help}</span></span>
              </Button>;
            })}
          </div>
        </section>)}
      </div>
      <Card id={previewId} className="min-w-0">
        <CardContent className="p-4 space-y-3">
          <h3 className="font-semibold">Vista previa</h3>
          <p className="text-sm text-muted-foreground">Solo es un ejemplo. No guarda ni envía información.</p>
          {selected ? <div className="space-y-3">
            <p className="font-medium">{selected.label}</p>
            <p className="text-sm">{selected.help}</p>
            <ToolPreview key={selected.id} tool={selected} />
          </div> : <p>Elige una herramienta para probarla aquí.</p>}
        </CardContent>
      </Card>
    </div>
  </section>;
}

export default VisualToolLibrary;

"""Contract checks for the isolated Fabric Studio visual library.

No network, database, credentials, or dependency installation is used.
The JSX check intentionally fails if the existing frontend parser is unavailable.
"""
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[2]
FRONTEND = ROOT / "frontend"
LIBRARY = FRONTEND / "src" / "components" / "fabric-studio"


def run_node(script):
    result = subprocess.run(
        ["node", "--input-type=module", "-e", script, str(FRONTEND)],
        cwd=ROOT,
        capture_output=True,
        text=True,
        timeout=30,
        check=False,
    )
    assert result.returncode == 0, result.stdout + result.stderr


def test_catalog_search_and_unique_immutable_tools():
    run_node(r"""
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
const path = join(process.argv[1], "src/components/fabric-studio/toolCatalog.js");
const source = readFileSync(path, "utf8");
const { VISUAL_TOOLS, searchVisualTools } = await import(
  "data:text/javascript;base64," + Buffer.from(source).toString("base64")
);
assert.equal(VISUAL_TOOLS.length, 6);
assert.equal(new Set(VISUAL_TOOLS.map(t => t.id)).size, VISUAL_TOOLS.length);
assert(Object.isFrozen(VISUAL_TOOLS));
for (const tool of VISUAL_TOOLS) {
  assert(Object.isFrozen(tool));
  for (const key of ["id", "category", "label", "help", "icon"]) {
    assert.equal(typeof tool[key], "string");
    assert(tool[key].trim());
  }
}
assert.deepEqual(searchVisualTools(" BOTON ").map(t => t.id), ["button"]);
assert.deepEqual(searchVisualTools("botón").map(t => t.id), ["button"]);
assert.equal(searchVisualTools("capturar información").length, 3);
assert.equal(searchVisualTools("noexiste").length, 0);
assert.equal(searchVisualTools("").length, VISUAL_TOOLS.length);
""")


def test_jsx_syntax_and_shared_ui_import_contracts():
    assert (LIBRARY / "VisualToolLibrary.jsx").is_file()
    run_node(r"""
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
const frontend = process.argv[1];
const require = createRequire(join(frontend, "package.json"));
const { parse } = require("@babel/parser");
const file = join(frontend, "src/components/fabric-studio/VisualToolLibrary.jsx");
const ast = path => parse(readFileSync(path, "utf8"), {
  sourceType: "module", plugins: ["jsx"]
}).program.body;
const imports = ast(file).filter(node => node.type === "ImportDeclaration");
const shared = imports.filter(node => node.source.value.startsWith("../ui/"));
assert(shared.length >= 4);
for (const node of shared) {
  const target = resolve(dirname(file), node.source.value);
  const exported = new Set();
  for (const declaration of ast(target)) {
    if (declaration.type !== "ExportNamedDeclaration") continue;
    for (const spec of declaration.specifiers) exported.add(spec.exported.name);
    const decl = declaration.declaration;
    if (decl?.id?.name) exported.add(decl.id.name);
    for (const item of decl?.declarations ?? []) {
      if (item.id?.name) exported.add(item.id.name);
    }
  }
  for (const spec of node.specifiers) {
    assert.equal(spec.type, "ImportSpecifier");
    assert(exported.has(spec.imported.name), target + ": " + spec.imported.name);
  }
}
for (const name of ["react", "lucide-react"]) require.resolve(name);
const icons = require("lucide-react");
for (const node of imports.filter(item => item.source.value === "lucide-react")) {
  for (const spec of node.specifiers) assert(icons[spec.imported.name], spec.imported.name);
}
const source = readFileSync(file, "utf8");
assert(source.includes("aria-pressed"));
assert(source.includes("aria-controls"));
assert(source.includes('role="status"'));
assert(source.includes("No guarda ni envía información"));
assert(imports.every(node => ["react", "lucide-react", "./toolCatalog.js"].includes(node.source.value) || node.source.value.startsWith("../ui/")));
""")
